<article class="product-card"><a href="{{ route('products.show', $product['slug']) }}"><div class="card-image"><img loading="lazy" src="{{ $product['images'][0] ?? '' }}" alt="{{ $product['name'] }}">@if(($product['discount_percentage'] ?? 0) > 0)<span class="tag">-{{ round($product['discount_percentage']) }} %</span>@elseif($product['new_arrival'] ?? false)<span class="tag">Nouveau</span>@endif</div><div class="card-copy"><small>{{ $product['brand'] ?? str_replace('-', ' ', $product['category']) }}</small><h3>{{ $product['name'] }}</h3><span class="price">{{ number_format($product['price'], 2, ',', ' ') }} {{ config('store.currency') }}</span>@if(isset($product['rating']))<small style="display:block;margin-top:8px">★ {{ number_format($product['rating'], 1, ',', ' ') }} / 5</small>@endif</div></a><form class="add-form" method="POST" action="{{ route('cart.add', $product['id']) }}">@csrf<input type="hidden" name="quantity" value="1"><button type="submit" @disabled(!$product['available'])>{{ $product['available'] ? 'Ajouter au panier' : 'Indisponible' }}</button></form></article>
